def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    out = [row[:] for row in grid]
    # Rectangular colored objects are identified by sizeable same-color
    # components; anomalous pixels within their bounding boxes are repaired.
    boxes = []
    for color in range(10):
        if color == bg:
            continue
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                stack = [(r, c)]
                seen.add((r, c))
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                grid[yy][xx] == color and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                if len(cells) >= 4:
                    a = min(y for y, x in cells); b = max(y for y, x in cells)
                    x0 = min(x for y, x in cells); x1 = max(x for y, x in cells)
                    boxes.append((a, b, x0, x1, color))
    claimed = set()
    for a, b, x0, x1, color in boxes:
        for y in range(a, b + 1):
            for x in range(x0, x1 + 1):
                if grid[y][x] != bg:
                    out[y][x] = color
                    claimed.add((y, x))
    # Isolated distractor pixels outside the solid objects are background.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in claimed:
                out[r][c] = bg
    return out
